CREATE TABLE auction_recovery.recovery_cases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), epoch bigint NOT NULL,
 operator_name text NOT NULL, reason text NOT NULL CHECK(length(btrim(reason))>=10),
 state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','RESET','ACTIVATED')),
 shutdown_evidence text, snapshot_hash text, approved_hash text,
 reset_approved_at timestamptz, activation_approved_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE UNIQUE INDEX one_open_scheduler_recovery ON auction_recovery.recovery_cases((true)) WHERE state='OPEN';
CREATE TABLE auction_recovery.reconciliations (
 action_id uuid PRIMARY KEY REFERENCES auction_recovery.lot_actions(id),
 case_id uuid NOT NULL REFERENCES auction_recovery.recovery_cases(id),
 operator_name text NOT NULL, evidence text NOT NULL CHECK(length(btrim(evidence))>=30),
 disposition text NOT NULL CHECK(disposition='MANUALLY_QUARANTINED_NO_REPLAY'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE auction_recovery.operator_events (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, case_id uuid NOT NULL REFERENCES auction_recovery.recovery_cases(id),
 operator_name text NOT NULL, event text NOT NULL, epoch bigint NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE FUNCTION auction_recovery.state_hash() RETURNS text LANGUAGE sql STABLE
SET search_path=pg_catalog,auction_recovery AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
  'actions',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY id),'[]'::jsonb) FROM auction_recovery.lot_actions a),
  'generations',(SELECT COALESCE(jsonb_agg(to_jsonb(g) ORDER BY kind,source_id),'[]'::jsonb) FROM auction_recovery.generations g),
  'reconciliation',(SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY action_id),'[]'::jsonb) FROM auction_recovery.reconciliations r)
 )::text,'UTF8')),'hex');
$$;
CREATE FUNCTION auction_recovery.begin_recovery(p_reason text) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE c auction_recovery.control%ROWTYPE; case_id uuid;
BEGIN
 PERFORM auction_recovery.require_operator();
 IF p_reason IS NULL OR length(btrim(p_reason))<10 THEN RAISE EXCEPTION 'RECOVERY_REASON_REQUIRED'; END IF;
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 UPDATE auction_recovery.control SET enabled=false,circuit='OPEN',epoch=epoch+1 WHERE singleton;
 INSERT INTO auction_recovery.recovery_cases(epoch,operator_name,reason) VALUES(c.epoch+1,session_user,p_reason) RETURNING id INTO case_id;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch) VALUES(case_id,session_user,'DISABLED_AND_FENCED',c.epoch+1);
 RETURN case_id;
END $$;
-- An administrative attestation is recorded as such, never inferred from a
-- missing transport record. It cannot mark business work completed or replay it.
CREATE FUNCTION auction_recovery.attest_shutdown(p_case uuid,p_evidence text) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCHER_MUST_BE_DISABLED'; END IF;
 IF p_evidence IS NULL OR length(btrim(p_evidence))<30 THEN RAISE EXCEPTION 'SHUTDOWN_EVIDENCE_REQUIRED'; END IF;
 UPDATE auction_recovery.recovery_cases SET shutdown_evidence=p_evidence,reset_approved_at=NULL,approved_hash=NULL WHERE id=p_case AND state='OPEN';
 IF NOT FOUND THEN RAISE EXCEPTION 'OPEN_RECOVERY_CASE_REQUIRED'; END IF;
END $$;
CREATE FUNCTION auction_recovery.approve_reset(p_case uuid) RETURNS text
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE h text;
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCHER_MUST_BE_DISABLED'; END IF;
 IF EXISTS(SELECT 1 FROM auction_recovery.lot_actions WHERE state='RECONCILIATION_REQUIRED') THEN RAISE EXCEPTION 'UNRECONCILED_ACTIONS'; END IF;
 h:=auction_recovery.state_hash();
 UPDATE auction_recovery.recovery_cases SET snapshot_hash=h,approved_hash=h,reset_approved_at=clock_timestamp()
  WHERE id=p_case AND state='OPEN' AND shutdown_evidence IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'SHUTDOWN_NOT_ATTESTED'; END IF;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch)
  SELECT id,session_user,'RESET_APPROVED',epoch FROM auction_recovery.recovery_cases WHERE id=p_case;
 RETURN h;
END $$;
CREATE FUNCTION auction_recovery.reset_scheduler_circuit_guarded(p_case uuid,p_expected_epoch bigint) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE c auction_recovery.control%ROWTYPE; rc auction_recovery.recovery_cases%ROWTYPE;
BEGIN
 PERFORM auction_recovery.require_operator();
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT rc FROM auction_recovery.recovery_cases WHERE id=p_case FOR UPDATE;
 IF p_expected_epoch IS NULL OR c.enabled OR c.epoch<>p_expected_epoch OR rc.epoch<>c.epoch THEN RAISE EXCEPTION 'DISABLED_CURRENT_EPOCH_REQUIRED'; END IF;
 IF rc.state<>'OPEN' OR rc.reset_approved_at IS NULL OR rc.reset_approved_at<clock_timestamp()-interval '15 minutes'
 OR rc.shutdown_evidence IS NULL OR rc.approved_hash IS DISTINCT FROM auction_recovery.state_hash() THEN RAISE EXCEPTION 'CURRENT_RECOVERY_APPROVAL_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM auction_recovery.lot_actions WHERE state='RECONCILIATION_REQUIRED') THEN RAISE EXCEPTION 'UNRECONCILED_ACTIONS'; END IF;
 UPDATE auction_recovery.control SET consecutive_failures=0,enabled=false,circuit='OPEN',epoch=epoch+1 WHERE singleton;
 UPDATE auction_recovery.recovery_cases SET state='RESET',epoch=c.epoch+1 WHERE id=p_case;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch) VALUES(p_case,session_user,'RESET_REMAINS_DISABLED',c.epoch+1);
END $$;
-- A separate administrative approval call is needed; reset never grants it.
CREATE FUNCTION auction_recovery.approve_activation(p_case uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCHER_MUST_BE_DISABLED'; END IF;
 UPDATE auction_recovery.recovery_cases SET activation_approved_at=clock_timestamp(),approved_hash=auction_recovery.state_hash()
 WHERE id=p_case AND state='RESET';
 IF NOT FOUND THEN RAISE EXCEPTION 'RESET_RECOVERY_CASE_REQUIRED'; END IF;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch)
 SELECT id,session_user,'ACTIVATION_APPROVED',epoch FROM auction_recovery.recovery_cases WHERE id=p_case;
END $$;
CREATE FUNCTION auction_recovery.activate_scheduler(p_case uuid,p_expected_epoch bigint) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE rc auction_recovery.recovery_cases%ROWTYPE;
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled AND epoch=p_expected_epoch FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISABLED_CURRENT_EPOCH_REQUIRED'; END IF;
 SELECT * INTO STRICT rc FROM auction_recovery.recovery_cases WHERE id=p_case FOR UPDATE;
 IF rc.state<>'RESET' OR rc.epoch<>p_expected_epoch OR rc.activation_approved_at IS NULL
 OR rc.activation_approved_at<clock_timestamp()-interval '15 minutes'
 OR rc.approved_hash IS DISTINCT FROM auction_recovery.state_hash()
 OR EXISTS(SELECT 1 FROM auction_recovery.lot_actions WHERE state='RECONCILIATION_REQUIRED') THEN RAISE EXCEPTION 'SEPARATE_ACTIVATION_APPROVAL_REQUIRED'; END IF;
 UPDATE auction_recovery.control SET enabled=true,circuit='CLOSED' WHERE singleton;
 UPDATE auction_recovery.recovery_cases SET state='ACTIVATED' WHERE id=p_case;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch) VALUES(p_case,session_user,'ACTIVATED',p_expected_epoch);
END $$;
ALTER TABLE auction_recovery.recovery_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE auction_recovery.reconciliations ENABLE ROW LEVEL SECURITY;
ALTER TABLE auction_recovery.operator_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;

-- Source: supabase/operations/auction-scheduler-workflows.sql
-- Local candidate, after engine/recovery. No cron or hosted activation.
CREATE TABLE auction_recovery.workflow_actions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auction_id uuid NOT NULL,
 subject_id uuid NOT NULL, generation bigint NOT NULL, auction_generation bigint NOT NULL,
 kind text NOT NULL CHECK(kind IN ('MINI_CLOSE','MINI_START','RESUME')),
 state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','COMPLETED','SUPERSEDED','RECONCILIATION_REQUIRED')),
 result jsonb, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(subject_id,generation,auction_generation,kind),
 CHECK((state='COMPLETED')=(completed_at IS NOT NULL AND result IS NOT NULL))
);
CREATE TABLE auction_recovery.mini_start_intents (
 session_id uuid NOT NULL, generation bigint NOT NULL, auction_generation bigint NOT NULL, auction_id uuid NOT NULL,
 host_id uuid NOT NULL, approved_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(session_id,generation,auction_generation)
);
CREATE FUNCTION public.request_mini_start(p_auction_id uuid,p_session_id uuid,p_closed_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auction_recovery,pg_temp AS $$
DECLARE s public.mini_auction_sessions%ROWTYPE; h uuid; g bigint; ag bigint; action_id uuid;
BEGIN
 SELECT r.host_id INTO h FROM public.rooms r JOIN public.auctions a ON a.room_id=r.id WHERE a.id=p_auction_id;
 IF auth.uid() IS NULL OR h IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'HOST_ONLY' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM auction_recovery.control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT s FROM public.mini_auction_sessions WHERE id=p_session_id AND auction_id=p_auction_id FOR UPDATE;
 g:=auction_recovery.generation('MINI',s.id);
 ag:=auction_recovery.generation('AUCTION',p_auction_id);
 IF s.closed_at IS DISTINCT FROM p_closed_at OR p_closed_at IS NULL THEN RAISE EXCEPTION 'STALE_MINI_REVIEW'; END IF;
 IF s.status NOT IN ('SELECTION_CLOSED','BIDDING') THEN RAISE EXCEPTION 'MINI_NOT_READY'; END IF;
 INSERT INTO auction_recovery.mini_start_intents(session_id,generation,auction_generation,auction_id,host_id) VALUES(s.id,g,ag,p_auction_id,h) ON CONFLICT DO NOTHING;
 INSERT INTO auction_recovery.workflow_actions(auction_id,subject_id,generation,auction_generation,kind)
 VALUES(p_auction_id,s.id,g,ag,'MINI_START') ON CONFLICT DO NOTHING;
 SELECT id INTO action_id FROM auction_recovery.workflow_actions WHERE subject_id=s.id AND generation=g AND auction_generation=ag AND kind='MINI_START';
 RETURN jsonb_build_object('success',true,'action_id',action_id,'generation',g);
END $$;
REVOKE ALL ON FUNCTION public.request_mini_start(uuid,uuid,timestamptz) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.request_mini_start(uuid,uuid,timestamptz) TO authenticated;

-- Derive the private transition from the authoritative implementation. Only its
-- caller check changes: real postgres plus a current persisted host intent.
-- No JWT/role impersonation; all lot/session updates and locks stay identical.
DO $clone$
DECLARE src text; auth_check text:='IF NOT v_is_service_role AND (v_user_id IS NULL OR v_room.host_id != v_user_id) THEN';
BEGIN
 src:=pg_get_functiondef('public.v3_start_mini_auction(uuid)'::regprocedure);
 IF position(auth_check in src)=0 OR position('CREATE OR REPLACE FUNCTION public.v3_start_mini_auction(' in src)<>1 THEN
  RAISE EXCEPTION 'MINI_START_SOURCE_DRIFT_REQUIRES_REVIEW';
 END IF;
 src:=replace(src,'CREATE OR REPLACE FUNCTION public.v3_start_mini_auction(','CREATE OR REPLACE FUNCTION auction_recovery.start_mini_transition(');
 src:=replace(src,auth_check,$replacement$
 PERFORM auction_recovery.require_operator();
 IF NOT EXISTS(SELECT 1 FROM auction_recovery.mini_start_intents i JOIN public.mini_auction_sessions s ON s.id=i.session_id
 WHERE i.auction_id=p_auction_id AND i.generation=auction_recovery.generation('MINI',s.id) AND i.auction_generation=auction_recovery.generation('AUCTION',p_auction_id) AND i.host_id=v_room.host_id) THEN
 $replacement$);
 EXECUTE src;
END $clone$;

-- In LEGACY ownership, synchronous host start records intent and result atomically.
-- In DATABASE ownership, direct host start is rejected; hosts must call
-- request_mini_start and let the native scheduler execute the transition.
-- The original business body remains private and non-API-callable.
DO $legacy$
DECLARE src text;
BEGIN
 src:=pg_get_functiondef('public.v3_start_mini_auction(uuid)'::regprocedure);
 src:=replace(src,'CREATE OR REPLACE FUNCTION public.v3_start_mini_auction(','CREATE OR REPLACE FUNCTION auction_recovery.legacy_host_start_transition(');
 EXECUTE src;
END $legacy$;
CREATE OR REPLACE FUNCTION public.v3_start_mini_auction(p_auction_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auction_recovery,pg_temp AS $$
DECLARE s public.mini_auction_sessions%ROWTYPE; h uuid; g bigint; ag bigint; w auction_recovery.workflow_actions%ROWTYPE; r jsonb;
BEGIN
 SELECT room.host_id INTO h FROM public.rooms room JOIN public.auctions a ON a.room_id=room.id WHERE a.id=p_auction_id;
 IF NOT COALESCE((auth.uid() IS NOT NULL AND h=auth.uid()) OR (current_setting('role',true)='service_role' AND auth.role()='service_role'),false) THEN
  RETURN jsonb_build_object('success',false,'error','ERR_UNAUTHORIZED');
 END IF;
 PERFORM 1 FROM auction_recovery.control WHERE singleton FOR UPDATE;
 -- Direct legacy mini starts are forbidden under database ownership.
 -- Hosts must use request_mini_start; only native recovery applies the transition.
 IF (SELECT delivery_owner FROM auction_recovery.control WHERE singleton)
    IS DISTINCT FROM 'LEGACY' THEN
  RETURN jsonb_build_object(
    'success',false,
    'error','DATABASE_SCHEDULER_OWNS_TICKS'
  );
 END IF;
 SELECT * INTO s FROM public.mini_auction_sessions WHERE auction_id=p_auction_id FOR UPDATE;
 IF s.id IS NULL THEN RETURN jsonb_build_object('success',false,'error','ERR_SESSION_NOT_FOUND'); END IF;
 g:=auction_recovery.generation('MINI',s.id);
 ag:=auction_recovery.generation('AUCTION',p_auction_id);
 IF auth.uid() IS NOT NULL AND h=auth.uid() THEN
  INSERT INTO auction_recovery.mini_start_intents(session_id,generation,auction_generation,auction_id,host_id) VALUES(s.id,g,ag,p_auction_id,h) ON CONFLICT DO NOTHING;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM auction_recovery.mini_start_intents WHERE session_id=s.id AND generation=g AND auction_generation=ag AND host_id=h) THEN
  RETURN jsonb_build_object('success',false,'error','HOST_INTENT_REQUIRED'); END IF;
 INSERT INTO auction_recovery.workflow_actions(auction_id,subject_id,generation,auction_generation,kind) VALUES(p_auction_id,s.id,g,ag,'MINI_START') ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT w FROM auction_recovery.workflow_actions WHERE subject_id=s.id AND generation=g AND auction_generation=ag AND kind='MINI_START' FOR UPDATE;
 IF w.state='COMPLETED' THEN RETURN w.result; END IF;
 IF w.state<>'PENDING' THEN RETURN jsonb_build_object('success',false,'error','WORKFLOW_RECONCILIATION_REQUIRED'); END IF;
 r:=auction_recovery.legacy_host_start_transition(p_auction_id);
 IF r->'success'='true'::jsonb THEN
  UPDATE auction_recovery.workflow_actions SET state='COMPLETED',result=r,completed_at=clock_timestamp() WHERE id=w.id;
 END IF;
 RETURN r;
END $$;

CREATE FUNCTION auction_recovery.workflow_resume_due(p_reason text) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN
 RETURN COALESCE((p_reason::jsonb->>'resume_expires_at')::numeric<=extract(epoch FROM now())*1000,false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END $$;
CREATE FUNCTION auction_recovery.plan_due_workflows(p_limit integer DEFAULT 25) RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery,public AS $$
DECLARE c auction_recovery.control%ROWTYPE; r record; n integer:=0; quarantined uuid;
BEGIN
 PERFORM auction_recovery.require_operator();
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'INVALID_PLAN_LIMIT'; END IF;
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 IF NOT c.enabled OR c.circuit<>'CLOSED' THEN RETURN 0; END IF;
 FOR r IN SELECT s.auction_id,s.id,auction_recovery.generation('MINI',s.id) AS generation,
 CASE WHEN s.status='SELECTION_OPEN' THEN 'MINI_CLOSE' ELSE 'MINI_START' END AS kind
 FROM public.mini_auction_sessions s WHERE (s.status='SELECTION_OPEN' AND s.selection_expires_at<=clock_timestamp())
 OR (s.status='SELECTION_CLOSED' AND EXISTS(SELECT 1 FROM auction_recovery.mini_start_intents i WHERE i.session_id=s.id
 AND i.generation=auction_recovery.generation('MINI',s.id) AND i.auction_generation=auction_recovery.generation('AUCTION',s.auction_id))) ORDER BY s.id LIMIT p_limit LOOP
 INSERT INTO auction_recovery.workflow_actions(auction_id,subject_id,generation,auction_generation,kind) VALUES(r.auction_id,r.id,r.generation,auction_recovery.generation('AUCTION',r.auction_id),r.kind)
 ON CONFLICT DO NOTHING; n:=n+1;
 END LOOP;
 FOR r IN SELECT a.id FROM public.auctions a WHERE status='PAUSED' AND auction_recovery.workflow_resume_due(a.paused_reason) IS DISTINCT FROM false
 AND NOT EXISTS(SELECT 1 FROM auction_recovery.workflow_actions w WHERE w.auction_id=a.id AND w.state='RECONCILIATION_REQUIRED') ORDER BY id LIMIT p_limit-n LOOP
  BEGIN
   IF (SELECT (paused_reason::jsonb->>'resume_expires_at')::numeric<=extract(epoch FROM clock_timestamp())*1000 FROM public.auctions WHERE id=r.id) THEN
    INSERT INTO auction_recovery.workflow_actions(auction_id,subject_id,generation,auction_generation,kind)
    VALUES(r.id,r.id,auction_recovery.generation('AUCTION',r.id),auction_recovery.generation('AUCTION',r.id),'RESUME') ON CONFLICT DO NOTHING;
    n:=n+1;
   END IF;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
   INSERT INTO auction_recovery.workflow_actions(auction_id,subject_id,generation,auction_generation,kind,state)
   VALUES(r.id,r.id,auction_recovery.generation('AUCTION',r.id),auction_recovery.generation('AUCTION',r.id),'RESUME','RECONCILIATION_REQUIRED') ON CONFLICT DO NOTHING RETURNING id INTO quarantined;
   IF quarantined IS NOT NULL THEN
    INSERT INTO auction_recovery.alert_outbox(dedupe_key,kind) VALUES('workflow:'||quarantined,'INVALID_RESUME_STATE') ON CONFLICT DO NOTHING;
   END IF;
  END;
 END LOOP;
 RETURN n;
END $$;

CREATE FUNCTION auction_recovery.apply_workflow(p_action uuid,p_epoch bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery,public AS $$
DECLARE c auction_recovery.control%ROWTYPE; w auction_recovery.workflow_actions%ROWTYPE;
 s public.mini_auction_sessions%ROWTYPE; au public.auctions%ROWTYPE; r jsonb; current_gen bigint;
BEGIN
 PERFORM auction_recovery.require_operator();
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 IF p_epoch IS NULL OR NOT c.enabled OR c.circuit<>'CLOSED' OR c.epoch<>p_epoch THEN RAISE EXCEPTION 'DISABLED_OR_STALE_EPOCH'; END IF;
 SELECT * INTO STRICT w FROM auction_recovery.workflow_actions WHERE id=p_action FOR UPDATE;
 IF w.state='COMPLETED' THEN RETURN w.result; END IF;
 IF w.state<>'PENDING' THEN RAISE EXCEPTION 'WORKFLOW_RECONCILIATION_REQUIRED'; END IF;
 SELECT * INTO STRICT au FROM public.auctions WHERE id=w.auction_id FOR UPDATE;
 current_gen:=auction_recovery.generation(CASE WHEN w.kind='RESUME' THEN 'AUCTION' ELSE 'MINI' END,w.subject_id);
 IF current_gen<>w.generation OR w.auction_generation<>auction_recovery.generation('AUCTION',w.auction_id) THEN
 UPDATE auction_recovery.workflow_actions SET state='SUPERSEDED' WHERE id=w.id;
 RETURN jsonb_build_object('success',false,'outcome','SAFE_DEFER_RACE'); END IF;
 BEGIN
  IF w.kind='RESUME' THEN
   IF au.status<>'PAUSED' OR NOT COALESCE((au.paused_reason::jsonb->>'resume_expires_at')::numeric<=extract(epoch FROM clock_timestamp())*1000,false) THEN RETURN jsonb_build_object('success',false,'outcome','SAFE_DEFER_RACE'); END IF;
   r:=public.resume_auction(w.auction_id);
  ELSE
   SELECT * INTO STRICT s FROM public.mini_auction_sessions WHERE id=w.subject_id AND auction_id=w.auction_id FOR UPDATE;
   IF w.kind='MINI_CLOSE' THEN
    IF s.status NOT IN ('SELECTION_OPEN','SELECTION_CLOSED','COMPLETED') OR (s.status='SELECTION_OPEN' AND (s.selection_expires_at IS NULL OR s.selection_expires_at>clock_timestamp())) THEN RETURN jsonb_build_object('success',false,'outcome','SAFE_DEFER_RACE'); END IF;
    IF s.status='SELECTION_OPEN' AND EXISTS(SELECT 1 FROM public.auction_lots WHERE auction_id=w.auction_id AND is_mini_round) THEN RAISE EXCEPTION 'INCONSISTENT_OPEN_MINI_POOL'; END IF;
    r:=public.v3_close_mini_selection(w.auction_id,false);
   ELSE
    IF NOT EXISTS(SELECT 1 FROM auction_recovery.mini_start_intents i JOIN public.rooms h ON h.id=au.room_id WHERE i.session_id=s.id AND i.generation=w.generation AND i.auction_generation=w.auction_generation AND i.host_id=h.host_id) THEN RAISE EXCEPTION 'HOST_INTENT_REQUIRED'; END IF;
    IF s.status='SELECTION_CLOSED' AND (s.total_lots<1
     OR (SELECT count(*) FROM public.auction_lots WHERE auction_id=w.auction_id AND is_mini_round AND status='PENDING')<>s.total_lots
     OR (SELECT count(DISTINCT player_id) FROM public.auction_lots WHERE auction_id=w.auction_id AND is_mini_round)<>s.total_lots) THEN RAISE EXCEPTION 'INCONSISTENT_CLOSED_MINI_POOL'; END IF;
    IF s.status='BIDDING' AND au.status='IN_PROGRESS' AND EXISTS(SELECT 1 FROM public.auction_lots WHERE id=au.current_lot_id AND auction_id=au.id AND is_mini_round AND status IN ('GET_READY','BIDDING')) THEN
     r:=jsonb_build_object('success',true,'status','BIDDING','already_started',true);
    ELSE r:=auction_recovery.start_mini_transition(w.auction_id); END IF;
   END IF;
  END IF;
  IF r->'success' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'WORKFLOW_TRANSITION_REJECTED'; END IF;
  UPDATE auction_recovery.workflow_actions SET state='COMPLETED',result=r,completed_at=clock_timestamp() WHERE id=w.id;
  UPDATE auction_recovery.control SET last_success_at=clock_timestamp() WHERE singleton;
  RETURN r;
 EXCEPTION WHEN OTHERS THEN
  UPDATE auction_recovery.workflow_actions SET state='RECONCILIATION_REQUIRED' WHERE id=w.id;
  UPDATE auction_recovery.control SET enabled=false,circuit='OPEN',consecutive_failures=consecutive_failures+1 WHERE singleton;
  INSERT INTO auction_recovery.alert_outbox(dedupe_key,kind) VALUES('workflow:'||w.id,'WORKFLOW_QUARANTINE') ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('success',false,'outcome','QUARANTINE_FAULT');
 END;
END $$;
CREATE PROCEDURE auction_recovery.run_workflow_tick(p_limit integer DEFAULT 25)
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE w record; e bigint;
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM auction_recovery.plan_due_workflows(p_limit);
 SELECT epoch INTO e FROM auction_recovery.control WHERE singleton;
 COMMIT;
 FOR w IN SELECT id FROM auction_recovery.workflow_actions WHERE state='PENDING' ORDER BY created_at,id LIMIT p_limit LOOP
  PERFORM auction_recovery.apply_workflow(w.id,e);
  COMMIT;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION auction_recovery.state_hash() RETURNS text LANGUAGE sql STABLE
SET search_path=pg_catalog,auction_recovery AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
  'actions',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY id),'[]'::jsonb) FROM auction_recovery.lot_actions a),
  'workflows',(SELECT COALESCE(jsonb_agg(to_jsonb(w) ORDER BY id),'[]'::jsonb) FROM auction_recovery.workflow_actions w),
  'intents',(SELECT COALESCE(jsonb_agg(to_jsonb(i) ORDER BY session_id,generation,auction_generation),'[]'::jsonb) FROM auction_recovery.mini_start_intents i),
  'generations',(SELECT COALESCE(jsonb_agg(to_jsonb(g) ORDER BY kind,source_id),'[]'::jsonb) FROM auction_recovery.generations g),
  'reconciliation',(SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY action_id),'[]'::jsonb) FROM auction_recovery.reconciliations r)
 )::text,'UTF8')),'hex');
$$;
CREATE FUNCTION auction_recovery.guard_workflow_recovery() RETURNS trigger LANGUAGE plpgsql
SET search_path=pg_catalog,auction_recovery AS $$ BEGIN
 IF (NEW.reset_approved_at IS NOT NULL OR NEW.activation_approved_at IS NOT NULL OR NEW.state IN ('RESET','ACTIVATED'))
 AND EXISTS(SELECT 1 FROM auction_recovery.workflow_actions WHERE state='RECONCILIATION_REQUIRED') THEN
  RAISE EXCEPTION 'UNRECONCILED_WORKFLOWS';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER recovery_requires_reconciled_workflows BEFORE UPDATE ON auction_recovery.recovery_cases
FOR EACH ROW EXECUTE FUNCTION auction_recovery.guard_workflow_recovery();
ALTER TABLE auction_recovery.workflow_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE auction_recovery.mini_start_intents ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON PROCEDURE auction_recovery.run_workflow_tick(integer) FROM PUBLIC,anon,authenticated,service_role;

-- Source: supabase/operations/auction-scheduler-claims.sql
-- Local candidate after workflows. No cron creation or activation.
ALTER TABLE auction_recovery.control ADD COLUMN delivery_owner text NOT NULL DEFAULT 'DATABASE' CHECK(delivery_owner IN ('DATABASE','LEGACY'));
CREATE FUNCTION public.auction_scheduler_owner() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,auction_recovery AS $$ SELECT delivery_owner FROM auction_recovery.control WHERE singleton $$;
REVOKE ALL ON FUNCTION public.auction_scheduler_owner() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.auction_scheduler_owner() TO service_role;
CREATE TABLE auction_recovery.claims (
 token uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN ('LOT','WORKFLOW')), epoch bigint NOT NULL,
 owner_name text NOT NULL, worker_id text NOT NULL CHECK(length(worker_id) BETWEEN 1 AND 100),
 state text NOT NULL DEFAULT 'CLAIMED' CHECK(state IN ('CLAIMED','COMPLETED','UNKNOWN','RESOLVED_NO_REPLAY')),
 lease_expires_at timestamptz NOT NULL, result jsonb,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE UNIQUE INDEX one_unresolved_claim ON auction_recovery.claims(kind,action_id) WHERE state IN ('CLAIMED','UNKNOWN');
CREATE FUNCTION auction_recovery.claim_action(p_action uuid,p_kind text,p_epoch bigint,p_worker text) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE c auction_recovery.control%ROWTYPE; t uuid;
BEGIN
 PERFORM auction_recovery.require_operator();
 IF p_epoch IS NULL OR p_kind IS NULL OR p_kind NOT IN ('LOT','WORKFLOW') OR p_worker IS NULL OR length(p_worker) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'INVALID_CLAIM'; END IF;
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 IF NOT c.enabled OR c.circuit<>'CLOSED' OR c.delivery_owner<>'DATABASE' OR c.epoch<>p_epoch THEN RAISE EXCEPTION 'CLAIMS_DISABLED_OR_FENCED'; END IF;
 IF p_kind='LOT' THEN
  PERFORM 1 FROM auction_recovery.lot_actions WHERE id=p_action AND state='PENDING' AND next_attempt_at<=clock_timestamp() FOR UPDATE;
 ELSE PERFORM 1 FROM auction_recovery.workflow_actions WHERE id=p_action AND state='PENDING' FOR UPDATE; END IF;
 IF NOT FOUND THEN
  -- A host or another executor can finish between planning and claiming. That
  -- is a harmless race, not a circuit failure or permission to replay.
  IF (p_kind='LOT' AND EXISTS(SELECT 1 FROM auction_recovery.lot_actions WHERE id=p_action))
   OR (p_kind='WORKFLOW' AND EXISTS(SELECT 1 FROM auction_recovery.workflow_actions WHERE id=p_action)) THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'ACTION_NOT_FOUND';
 END IF;
 INSERT INTO auction_recovery.claims(action_id,kind,epoch,owner_name,worker_id,lease_expires_at)
 VALUES(p_action,p_kind,p_epoch,session_user,p_worker,clock_timestamp()+interval '30 seconds') ON CONFLICT DO NOTHING RETURNING token INTO t;
 -- Existing/expired claims are never silently stolen.
 RETURN t;
END $$;
CREATE FUNCTION auction_recovery.execute_claim(p_token uuid,p_epoch bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE c auction_recovery.control%ROWTYPE; cl auction_recovery.claims%ROWTYPE; r jsonb;
BEGIN
 PERFORM auction_recovery.require_operator();
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT cl FROM auction_recovery.claims WHERE token=p_token FOR UPDATE;
 IF p_epoch IS NULL OR NOT c.enabled OR c.circuit<>'CLOSED' OR c.delivery_owner<>'DATABASE' OR c.epoch<>p_epoch OR cl.epoch<>p_epoch THEN RAISE EXCEPTION 'CLAIM_FENCED'; END IF;
 IF cl.state='COMPLETED' THEN RETURN cl.result; END IF;
 IF cl.state<>'CLAIMED' OR cl.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CLAIM_RECONCILIATION_REQUIRED'; END IF;
 IF cl.kind='LOT' THEN r:=auction_recovery.apply_lot_action(cl.action_id,p_epoch);
 ELSE r:=auction_recovery.apply_workflow(cl.action_id,p_epoch); END IF;
 -- This delivery attempt is complete even on a known safe defer. A later due
 -- action may have a new claim; replaying this token only returns this result.
 UPDATE auction_recovery.claims SET state='COMPLETED',result=r WHERE token=cl.token;
 RETURN r;
END $$;
CREATE FUNCTION auction_recovery.reconcile_claim(p_token uuid) RETURNS text
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE cl auction_recovery.claims%ROWTYPE; s text; r jsonb;
BEGIN
 PERFORM auction_recovery.require_operator();
 -- If an old action transaction is running, this lock waits for its commit or
 -- rollback before checking outcome. Lease expiry is not process termination.
 PERFORM 1 FROM auction_recovery.control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT cl FROM auction_recovery.claims WHERE token=p_token FOR UPDATE;
 IF cl.state IN ('COMPLETED','RESOLVED_NO_REPLAY') THEN RETURN cl.state; END IF;
 IF cl.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'VALID_LEASE_REMAINS'; END IF;
 IF cl.kind='LOT' THEN SELECT state,result INTO s,r FROM auction_recovery.lot_actions WHERE id=cl.action_id FOR UPDATE;
 ELSE SELECT state,result INTO s,r FROM auction_recovery.workflow_actions WHERE id=cl.action_id FOR UPDATE; END IF;
 IF s='COMPLETED' THEN UPDATE auction_recovery.claims SET state='COMPLETED',result=r WHERE token=cl.token; RETURN 'COMPLETED'; END IF;
 UPDATE auction_recovery.claims SET state='UNKNOWN' WHERE token=cl.token;
 IF cl.kind='LOT' THEN UPDATE auction_recovery.lot_actions SET state='RECONCILIATION_REQUIRED' WHERE id=cl.action_id;
 ELSE UPDATE auction_recovery.workflow_actions SET state='RECONCILIATION_REQUIRED' WHERE id=cl.action_id; END IF;
 UPDATE auction_recovery.control SET enabled=false,circuit='OPEN' WHERE singleton;
 INSERT INTO auction_recovery.alert_outbox(dedupe_key,kind) VALUES('unknown:'||cl.token,'UNKNOWN_CLAIM') ON CONFLICT DO NOTHING;
 RETURN 'UNKNOWN';
END $$;
CREATE TABLE auction_recovery.claim_dispositions (
 token uuid PRIMARY KEY REFERENCES auction_recovery.claims(token),
 case_id uuid NOT NULL REFERENCES auction_recovery.recovery_cases(id),
 operator_name text NOT NULL, evidence text NOT NULL CHECK(length(btrim(evidence))>=50),
 resolution text NOT NULL CHECK(resolution='NO_REPLAY'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE FUNCTION auction_recovery.resolve_claim_no_replay(p_case uuid,p_token uuid,p_evidence text) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE cl auction_recovery.claims%ROWTYPE;
BEGIN
 PERFORM auction_recovery.require_operator();
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCHER_MUST_BE_DISABLED'; END IF;
 PERFORM 1 FROM auction_recovery.recovery_cases WHERE id=p_case AND state='OPEN' AND shutdown_evidence IS NOT NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SHUTDOWN_EVIDENCE_REQUIRED'; END IF;
 SELECT * INTO STRICT cl FROM auction_recovery.claims WHERE token=p_token FOR UPDATE;
 IF cl.state<>'UNKNOWN' OR cl.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'UNKNOWN_EXPIRED_CLAIM_REQUIRED'; END IF;
 INSERT INTO auction_recovery.claim_dispositions(token,case_id,operator_name,evidence,resolution) VALUES(p_token,p_case,session_user,p_evidence,'NO_REPLAY');
 UPDATE auction_recovery.claims SET state='RESOLVED_NO_REPLAY' WHERE token=p_token;
 IF cl.kind='LOT' THEN UPDATE auction_recovery.lot_actions SET state='SUPERSEDED' WHERE id=cl.action_id AND state='RECONCILIATION_REQUIRED';
 ELSE UPDATE auction_recovery.workflow_actions SET state='SUPERSEDED' WHERE id=cl.action_id AND state='RECONCILIATION_REQUIRED'; END IF;
 UPDATE auction_recovery.recovery_cases SET approved_hash=NULL,reset_approved_at=NULL WHERE id=p_case;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch)
 SELECT p_case,session_user,'CLAIM_RESOLVED_NO_REPLAY',epoch FROM auction_recovery.control WHERE singleton;
END $$;
CREATE FUNCTION auction_recovery.guard_claim_recovery() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,auction_recovery AS $$ BEGIN
 IF (NEW.reset_approved_at IS NOT NULL OR NEW.activation_approved_at IS NOT NULL OR NEW.state IN ('RESET','ACTIVATED'))
 AND EXISTS(SELECT 1 FROM auction_recovery.claims WHERE state IN ('CLAIMED','UNKNOWN')) THEN RAISE EXCEPTION 'UNRECONCILED_CLAIMS'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER recovery_requires_reconciled_claims BEFORE UPDATE ON auction_recovery.recovery_cases FOR EACH ROW EXECUTE FUNCTION auction_recovery.guard_claim_recovery();
-- Known failed actions also need an audited disposition; a completed delivery
-- claim is not proof that the business action succeeded. Never replay or repair
-- financial state here. A new business intent requires separate review.
CREATE TABLE auction_recovery.action_dispositions (
 kind text NOT NULL CHECK(kind IN ('LOT','WORKFLOW')), action_id uuid NOT NULL,
 case_id uuid NOT NULL REFERENCES auction_recovery.recovery_cases(id),
 operator_name text NOT NULL, evidence text NOT NULL CHECK(length(btrim(evidence))>=50),
 resolution text NOT NULL CHECK(resolution='NO_REPLAY'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(kind,action_id)
);
CREATE FUNCTION auction_recovery.resolve_action_no_replay(p_case uuid,p_action uuid,p_kind text,p_evidence text) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,auction_recovery AS $$
BEGIN
 PERFORM auction_recovery.require_operator();
 IF p_kind IS NULL OR p_kind NOT IN ('LOT','WORKFLOW') THEN RAISE EXCEPTION 'INVALID_ACTION_KIND'; END IF;
 PERFORM 1 FROM auction_recovery.control WHERE singleton AND NOT enabled FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCHER_MUST_BE_DISABLED'; END IF;
 PERFORM 1 FROM auction_recovery.recovery_cases WHERE id=p_case AND state='OPEN' AND shutdown_evidence IS NOT NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SHUTDOWN_EVIDENCE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM auction_recovery.claims WHERE action_id=p_action AND kind=p_kind AND state IN ('CLAIMED','UNKNOWN')) THEN
  RAISE EXCEPTION 'RECONCILE_CLAIM_FIRST'; END IF;
 IF p_kind='LOT' THEN
  UPDATE auction_recovery.lot_actions SET state='SUPERSEDED' WHERE id=p_action AND state='RECONCILIATION_REQUIRED';
 ELSE
  UPDATE auction_recovery.workflow_actions SET state='SUPERSEDED' WHERE id=p_action AND state='RECONCILIATION_REQUIRED';
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'QUARANTINED_ACTION_REQUIRED'; END IF;
 INSERT INTO auction_recovery.action_dispositions(kind,action_id,case_id,operator_name,evidence,resolution)
 VALUES(p_kind,p_action,p_case,session_user,p_evidence,'NO_REPLAY');
 UPDATE auction_recovery.recovery_cases SET approved_hash=NULL,reset_approved_at=NULL WHERE id=p_case;
 INSERT INTO auction_recovery.operator_events(case_id,operator_name,event,epoch)
 SELECT p_case,session_user,'ACTION_RESOLVED_NO_REPLAY',epoch FROM auction_recovery.control WHERE singleton;
END $$;
ALTER TABLE auction_recovery.claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE auction_recovery.claim_dispositions ENABLE ROW LEVEL SECURITY;
ALTER TABLE auction_recovery.action_dispositions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;

-- Source: supabase/operations/auction-scheduler-runtime.sql
-- Local candidate after claims. No cron jobs created or activated.
CREATE PROCEDURE auction_recovery.run_native_tick(p_budget integer DEFAULT 25)
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE t record; expected_epoch bigint; token uuid; execution uuid; c auction_recovery.control%ROWTYPE;
 started timestamptz:=clock_timestamp(); old_tx_timeout text:=current_setting('transaction_timeout'); old_lock_timeout text:=current_setting('lock_timeout');
BEGIN
 PERFORM auction_recovery.require_operator();
 IF p_budget IS NULL OR p_budget NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'INVALID_TICK_BUDGET'; END IF;
 -- PostgreSQL 17's transaction timeout arms even when assigned inside a running
 -- transaction. It terminates a stalled backend; committed claims then require
 -- reconciliation. These settings apply only to this job session.
 PERFORM set_config('transaction_timeout','3s',false);
 PERFORM set_config('lock_timeout','500ms',false);
 <<slice>>
 BEGIN
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton FOR UPDATE;
 IF NOT c.enabled OR c.circuit<>'CLOSED' OR c.delivery_owner<>'DATABASE' THEN EXIT slice; END IF;
 UPDATE auction_recovery.control SET last_tick_at=clock_timestamp() WHERE singleton;
 expected_epoch:=c.epoch;
 COMMIT;
 FOR t IN SELECT cl.token FROM auction_recovery.claims cl WHERE cl.state='CLAIMED' AND cl.lease_expires_at<=clock_timestamp() ORDER BY cl.lease_expires_at LIMIT 5 LOOP
  PERFORM auction_recovery.reconcile_claim(t.token);
  COMMIT;
 END LOOP;
 SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton;
 IF NOT c.enabled OR c.epoch<>expected_epoch THEN EXIT slice; END IF;
 PERFORM auction_recovery.plan_due_workflows(LEAST(5,p_budget-1));
 execution:=auction_recovery.plan_due_auction_actions(10,p_budget-LEAST(5,p_budget-1),'pg_cron');
 COMMIT;
 FOR t IN SELECT id,'WORKFLOW'::text AS kind,created_at FROM auction_recovery.workflow_actions WHERE state='PENDING'
  UNION ALL SELECT a.id,'LOT',a.created_at FROM auction_recovery.lot_actions a JOIN auction_recovery.execution_actions e ON e.action_id=a.id WHERE e.execution_id=execution AND a.state='PENDING'
  ORDER BY created_at,id LIMIT p_budget LOOP
  EXIT WHEN clock_timestamp()>started+interval '5 seconds';
  SELECT * INTO STRICT c FROM auction_recovery.control WHERE singleton;
  IF NOT c.enabled OR c.epoch<>expected_epoch THEN EXIT slice; END IF;
  token:=auction_recovery.claim_action(t.id,t.kind,expected_epoch,'pg_cron');
  COMMIT;
  IF token IS NOT NULL THEN
   PERFORM auction_recovery.execute_claim(token,expected_epoch);
   COMMIT;
  END IF;
 END LOOP;
 IF execution IS NOT NULL THEN
  UPDATE auction_recovery.executions e SET state=CASE
   WHEN EXISTS(SELECT 1 FROM auction_recovery.execution_actions x JOIN auction_recovery.lot_actions a ON a.id=x.action_id WHERE x.execution_id=e.id AND a.state='RECONCILIATION_REQUIRED') THEN 'QUARANTINED'
   WHEN EXISTS(SELECT 1 FROM auction_recovery.execution_actions x JOIN auction_recovery.lot_actions a ON a.id=x.action_id WHERE x.execution_id=e.id AND a.state='PENDING') THEN 'PARTIAL' ELSE 'COMPLETED' END,
   completed_at=clock_timestamp() WHERE id=execution;
 END IF;
 COMMIT;
 END slice;
 PERFORM set_config('transaction_timeout',old_tx_timeout,false);
 PERFORM set_config('lock_timeout',old_lock_timeout,false);
END $$;
CREATE FUNCTION public.auction_scheduler_health() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,auction_recovery AS $$
 SELECT jsonb_build_object('schemaVersion',1,'enabled',c.enabled,'owner',c.delivery_owner,
 'epoch',c.epoch,'circuit',c.circuit,'lastTickAt',c.last_tick_at,'lastSuccessAt',c.last_success_at,
 'stale',c.enabled AND (c.last_tick_at IS NULL OR c.last_tick_at<clock_timestamp()-interval '15 seconds'),
 'unknownClaims',(SELECT count(*) FROM auction_recovery.claims WHERE state='UNKNOWN'),
 'quarantinedActions',(SELECT count(*) FROM auction_recovery.lot_actions WHERE state='RECONCILIATION_REQUIRED')+(SELECT count(*) FROM auction_recovery.workflow_actions WHERE state='RECONCILIATION_REQUIRED'),
 'undeliveredAlerts',(SELECT count(*) FROM auction_recovery.alert_outbox WHERE delivered_at IS NULL))
 FROM auction_recovery.control c WHERE singleton;
$$;
REVOKE ALL ON FUNCTION public.auction_scheduler_health() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.auction_scheduler_health() TO service_role;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='auction_monitor') THEN CREATE ROLE auction_monitor NOLOGIN; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='auction_monitor' AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb)) THEN RAISE EXCEPTION 'UNSAFE_EXISTING_MONITOR_ROLE'; END IF;
END $$;
GRANT USAGE ON SCHEMA public TO auction_monitor;
GRANT EXECUTE ON FUNCTION public.auction_scheduler_health() TO auction_monitor;
REVOKE ALL ON PROCEDURE auction_recovery.run_native_tick(integer) FROM PUBLIC,anon,authenticated,service_role;

-- Source: supabase/operations/auction-scheduler-alerts.sql
-- Local candidate. External delivery remains a separately provisioned process.
ALTER TABLE auction_recovery.alert_outbox ADD COLUMN delivery_token uuid;
ALTER TABLE auction_recovery.alert_outbox ADD COLUMN delivery_lease_until timestamptz;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='auction_alert_sender') THEN CREATE ROLE auction_alert_sender NOLOGIN; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='auction_alert_sender' AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb)) THEN RAISE EXCEPTION 'UNSAFE_EXISTING_ALERT_ROLE'; END IF;
END $$;
CREATE FUNCTION public.claim_scheduler_alerts(p_limit integer DEFAULT 10) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auction_recovery AS $$
DECLARE r record; payload jsonb:='[]'::jsonb; t uuid;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'INVALID_ALERT_LIMIT'; END IF;
 FOR r IN SELECT * FROM auction_recovery.alert_outbox WHERE delivered_at IS NULL AND next_attempt_at<=clock_timestamp()
 AND (delivery_lease_until IS NULL OR delivery_lease_until<=clock_timestamp()) ORDER BY id LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
  t:=gen_random_uuid();
  UPDATE auction_recovery.alert_outbox SET delivery_token=t,delivery_lease_until=clock_timestamp()+interval '30 seconds',
   attempts=attempts+1,next_attempt_at=clock_timestamp()+make_interval(secs=>LEAST(300,power(2,LEAST(attempts,8))::integer)) WHERE id=r.id;
  payload:=payload||jsonb_build_array(jsonb_build_object('id',r.id,'kind',r.kind,'dedupeKey',r.dedupe_key,'token',t));
 END LOOP;
 RETURN payload;
END $$;
CREATE FUNCTION public.ack_scheduler_alert(p_id bigint,p_token uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auction_recovery AS $$ BEGIN
 UPDATE auction_recovery.alert_outbox SET delivered_at=clock_timestamp(),delivery_lease_until=NULL
 WHERE id=p_id AND delivery_token=p_token AND delivered_at IS NULL;
 RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION public.claim_scheduler_alerts(integer),public.ack_scheduler_alert(bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT USAGE ON SCHEMA public TO auction_alert_sender;
GRANT EXECUTE ON FUNCTION public.claim_scheduler_alerts(integer),public.ack_scheduler_alert(bigint,uuid) TO auction_alert_sender;

-- Source: supabase/operations/auction-scheduler-fencing.sql
-- Database-side fence also covers older immutable application deployments.
-- Original timer business bodies/ACLs remain behind mode-aware wrappers.
DO $fence$
DECLARE signature text; p record; src text; original_name text; arguments text;
BEGIN
 FOREACH signature IN ARRAY ARRAY[
  'public.v3_start_bidding(uuid,uuid)','public.v3_start_bidding(uuid,uuid,boolean)',
  'public.v3_finalize_and_advance_lot(uuid,uuid)','public.v3_finalize_and_advance_lot(uuid,uuid,boolean)',
  'public.v3_close_mini_selection(uuid,boolean)','public.v3_start_mini_auction(uuid)','public.resume_auction(uuid)',
  'public.activate_lot_timer(uuid,uuid)','public.process_lot_expiry(uuid,uuid)','public.advance_lot(uuid)'
 ] LOOP
  SELECT * INTO STRICT p FROM pg_proc WHERE oid=signature::regprocedure;
  IF p.prorettype<>'jsonb'::regtype OR NOT p.prosecdef OR cardinality(p.proargnames)<>p.pronargs THEN
   RAISE EXCEPTION 'TIMER_RPC_SIGNATURE_DRIFT: %',signature;
  END IF;
  original_name:='legacy_timer_'||p.proname||'_'||p.pronargs;
  src:=pg_get_functiondef(p.oid);
  IF position(format('CREATE OR REPLACE FUNCTION public.%I(',p.proname) in src)<>1 THEN RAISE EXCEPTION 'TIMER_RPC_SOURCE_DRIFT'; END IF;
  src:=replace(src,format('CREATE OR REPLACE FUNCTION public.%I(',p.proname),format('CREATE OR REPLACE FUNCTION auction_recovery.%I(',original_name));
  EXECUTE src;
  SELECT string_agg(format('%I',name),',' ORDER BY position) INTO arguments FROM unnest(p.proargnames) WITH ORDINALITY x(name,position);
  EXECUTE format($wrapper$
   CREATE OR REPLACE FUNCTION public.%I(%s) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
   SET search_path=pg_catalog,auction_recovery,public,pg_temp AS $body$
   BEGIN
    IF current_setting('role',true)='service_role' AND COALESCE((SELECT delivery_owner FROM auction_recovery.control WHERE singleton),'DATABASE')<>'LEGACY' THEN
     RETURN jsonb_build_object('success',false,'error','DATABASE_SCHEDULER_OWNS_TICKS');
    END IF;
    RETURN auction_recovery.%I(%s);
   END $body$;
  $wrapper$,p.proname,pg_get_function_arguments(p.oid),original_name,arguments);
 END LOOP;
END $fence$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auction_recovery FROM PUBLIC,anon,authenticated,service_role;

NOTIFY pgrst, 'reload schema';
COMMIT;
